package in.paisa.personal;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.Build;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.zip.*;

/** Optional cloud work runs outside the local WebView and never receives raw SMS. */
public final class CloudSync {
 public static final String ORIGIN="https://paisa-fuzail.vercel.app";
 private static final int LIMIT=16*1024*1024;
 private static final ExecutorService EXECUTOR=Executors.newSingleThreadExecutor();
 private static final class ApiError extends IOException {final int status;ApiError(int s,String text){super(text);status=s;}}
 public static void execute(Runnable action){EXECUTOR.execute(action);}
 public static void kick(Context context){if(CloudJobs.active(context)||new CloudVault(context).exists("pending"))execute(()->run(context,""));}
 private static String hash(String text)throws Exception{byte[] digest=MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte value:digest)b.append(String.format("%02x",value));return b.toString();}
 private static String random(){byte[] b=new byte[32];new SecureRandom().nextBytes(b);return android.util.Base64.encodeToString(b,android.util.Base64.URL_SAFE|android.util.Base64.NO_WRAP|android.util.Base64.NO_PADDING);}
 private static void changed(Context c){c.sendBroadcast(new Intent("in.paisa.DATA_CHANGED").setPackage(c.getPackageName()));}
 private static void meta(Context c,CloudVault vault,JSONObject m)throws Exception{vault.write("meta",m);changed(c);}
 private static JSONObject api(JSONObject m,String action,JSONObject body)throws Exception{
  String target=ORIGIN+"/api/paisa?action="+action;HttpURLConnection connection=(HttpURLConnection)new URL(target).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(15000);connection.setReadTimeout(30000);connection.setRequestProperty("X-Paisa-Client","android");connection.setRequestProperty("Accept","application/json");if(!m.optString("token").isEmpty())connection.setRequestProperty("Authorization","Bearer "+m.getString("token"));
  try{if(body!=null){connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");try(OutputStream out=connection.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}
   int status=connection.getResponseCode();InputStream stream=status<400?connection.getInputStream():connection.getErrorStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream();if(stream!=null)try(InputStream in=stream){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(bytes.size()+n>2000000)throw new IOException("Cloud reply is too large");bytes.write(buffer,0,n);}}
   JSONObject result;try{result=new JSONObject(new String(bytes.toByteArray(),StandardCharsets.UTF_8));}catch(Exception e){throw new IOException("Cloud sync is temporarily unavailable. Local records are safe.");}if(status<200||status>=300)throw new ApiError(status,result.optString("error","Cloud sync is temporarily unavailable"));return result;
  }finally{connection.disconnect();}
 }
 private static String encode(JSONObject state)throws Exception{byte[] input=state.toString().getBytes(StandardCharsets.UTF_8);if(input.length>LIMIT)throw new IOException("This workspace is too large for cloud sync. Use a manual encrypted backup.");ByteArrayOutputStream out=new ByteArrayOutputStream();try(GZIPOutputStream gzip=new GZIPOutputStream(out)){gzip.write(input);}return android.util.Base64.encodeToString(out.toByteArray(),android.util.Base64.NO_WRAP);}
 private static JSONObject decode(String encoded)throws Exception{byte[] compressed=android.util.Base64.decode(encoded,android.util.Base64.DEFAULT);ByteArrayOutputStream out=new ByteArrayOutputStream();try(GZIPInputStream in=new GZIPInputStream(new ByteArrayInputStream(compressed))){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>LIMIT)throw new IOException("Cloud copy is too large");out.write(buffer,0,n);}}return SyncCore.snapshot(new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8)));}
 private static JSONObject readRemote(JSONObject m,long revision)throws Exception{JSONObject head=api(m,"read&revision="+revision,null);StringBuilder encoded=new StringBuilder();int parts=head.getInt("parts");if(parts<1||parts>512)throw new IOException("Invalid cloud copy");for(int i=0;i<parts;i++){encoded.append(api(m,"read&revision="+head.getLong("revision")+"&part="+i,null).getString("data"));if(encoded.length()>LIMIT)throw new IOException("Cloud copy is too large");}if(encoded.length()!=head.getInt("bytes")||!hash(encoded.toString()).equals(head.getString("hash")))throw new IOException("Cloud copy is incomplete. Retry without changing local records.");return decode(encoded.toString());}
 private static JSONObject upload(JSONObject m,JSONObject state,long revision)throws Exception{String encoded=encode(state),id="";try{int parts=(encoded.length()+65535)/65536;JSONObject start=api(m,"upload.begin",new JSONObject().put("baseRevision",revision).put("parts",parts).put("hash",hash(encoded)).put("bytes",encoded.length()).put("entryCount",SyncCore.count(state)));id=start.getString("id");for(int i=0;i<parts;i++)api(m,"upload.part",new JSONObject().put("id",id).put("part",i).put("data",encoded.substring(i*65536,Math.min(encoded.length(),(i+1)*65536))));return api(m,"upload.commit",new JSONObject().put("id",id));}catch(Exception e){if(!id.isEmpty())try{api(m,"upload.abort",new JSONObject().put("id",id));}catch(Exception ignored){}throw e;}}
 private static boolean empty(JSONObject s)throws Exception{if(s.getJSONArray("entries").length()>0||s.getJSONArray("rules").length()>0||s.getJSONArray("bills").length()>0||s.getJSONArray("subscriptions").length()>0||s.getJSONArray("seen").length()>0)return false;JSONObject cfg=s.getJSONObject("settings");if(cfg.optLong("monthBudget")!=0||cfg.optJSONObject("categoryBudgets").length()>0)return false;JSONArray accounts=s.getJSONArray("accounts");for(int i=0;i<accounts.length();i++){JSONObject a=accounts.getJSONObject(i);if(!Arrays.asList("cash","bank:default").contains(a.optString("id"))||a.optLong("opening")!=0||a.has("snapshot"))return false;}return true;}
 private static JSONObject backup(Context c)throws Exception{try(Store store=new Store(c)){return store.backup();}}
 private static void validate(Context c,JSONObject shared)throws Exception{JSONObject full=SyncCore.compose(backup(c),shared);Ledger.validate(full);}
 private static void failure(Context c,CloudVault vault,JSONObject m,Exception e){try{m.put("error",e.getMessage()==null?"Cloud sync is unavailable. Local records are safe.":e.getMessage());if(e instanceof ApiError&&((ApiError)e).status==401){if(vault.exists("pending")&&vault.read("pending").optString("kind").equals("restore"))finishRestore(c,vault,m);m.remove("token");m.remove("pair");m.put("enabled",false).put("error","Sign in again to continue sync. Your local records are safe.");CloudJobs.cancel(c);}meta(c,vault,m);}catch(Exception ignored){}}
 public static JSONObject status(Context c){try{CloudVault vault=new CloudVault(c);JSONObject m=vault.read("meta"),pair=m.optJSONObject("pair"),user=m.optJSONObject("user");boolean connected=!m.optString("token").isEmpty();JSONObject result=new JSONObject().put("available",true).put("connected",connected).put("enabled",connected&&m.optBoolean("enabled")).put("user",connected&&user!=null?user:JSONObject.NULL).put("boundEmail",m.optString("boundEmail")).put("accountMismatch",connected&&!m.optString("boundId").isEmpty()&&!m.optString("boundId").equals(user.optString("id"))).put("error",m.optString("error")).put("lastSyncAt",m.optLong("lastSyncAt")).put("backupAt",m.optLong("backupAt")).put("head",m.optJSONObject("head")==null?new JSONObject():m.getJSONObject("head")).put("dirty",c.getSharedPreferences("cloud-flags",Context.MODE_PRIVATE).getBoolean("dirty",false)).put("canResume",connected&&user!=null&&m.optString("boundId").equals(user.optString("id"))&&vault.exists("base")).put("safetyAvailable",vault.exists("safety")).put("webUrl",ORIGIN+"/");if(pair!=null)result.put("pairCode",pair.optString("code")).put("pairExpires",pair.optLong("expires"));if(vault.exists("conflict"))result.put("conflicts",vault.read("conflict").optJSONArray("conflicts"));return result;}catch(Exception e){try{return new JSONObject().put("available",true).put("connected",false).put("enabled",false).put("error","Private cloud state could not be opened. Local records are safe.");}catch(Exception ignored){return new JSONObject();}}}
 private static boolean finishPending(Context c,CloudVault vault,JSONObject m,String resolution)throws Exception{
  JSONObject pending=vault.read("pending");if(!pending.has("uploaded"))return true;if(!pending.getString("owner").equals(m.getJSONObject("user").getString("id")))throw new IOException("Cloud account changed. Local records were not replaced.");
  for(int attempt=0;attempt<4;attempt++){JSONObject current=backup(c),local=SyncCore.snapshot(current);JSONObject previous=vault.exists("conflict")?vault.read("conflict"):new JSONObject();if(!resolution.isEmpty()&&previous.has("local")&&!SyncCore.same(previous.getJSONObject("local"),local)){resolution="";}
   SyncCore.Result rebased=SyncCore.merge(pending.getJSONObject("before"),local,pending.getJSONObject("uploaded"),resolution);
   if(rebased.conflicts.length()>0&&resolution.isEmpty()){vault.write("conflict",new JSONObject().put("phase","rebase").put("base",pending.getJSONObject("before")).put("local",local).put("remote",pending.getJSONObject("uploaded")).put("revision",pending.getJSONObject("head").getLong("revision")).put("conflicts",rebased.conflicts));m.put("error","");meta(c,vault,m);return false;}
   JSONObject composed=SyncCore.compose(current,rebased.state);Ledger.validate(composed);try(Store store=new Store(c)){try{store.applyCloud(current,composed);}catch(java.util.ConcurrentModificationException changed){continue;}}
   vault.write("base",new JSONObject().put("owner",m.getJSONObject("user").getString("id")).put("state",pending.getJSONObject("uploaded")));vault.remove("pending");vault.remove("conflict");JSONObject head=pending.getJSONObject("head");m.put("head",head).put("lastSyncAt",System.currentTimeMillis()).put("backupAt",head.optLong("updated")).put("error","");boolean dirty=!SyncCore.same(rebased.state,pending.getJSONObject("uploaded"));c.getSharedPreferences("cloud-flags",Context.MODE_PRIVATE).edit().putBoolean("dirty",dirty).apply();meta(c,vault,m);if(dirty)CloudJobs.schedule(c);return true;
  }throw new IOException("New activity arrived during sync. Records are safe; retrying shortly.");
 }
 public static boolean run(Context context,String resolution){Context c=context.getApplicationContext();CloudVault vault=new CloudVault(c);JSONObject m=new JSONObject();try{
  m=vault.read("meta");JSONObject pair=m.optJSONObject("pair");if(pair!=null){if(pair.optLong("expires")<System.currentTimeMillis()){m.remove("pair");m.put("error","Google connection link expired. Start again.");meta(c,vault,m);return false;}JSONObject claim=api(new JSONObject(),"pair.claim",new JSONObject().put("id",pair.getString("id")).put("verifier",pair.getString("verifier")));if(claim.optBoolean("pending"))return true;if(!claim.optString("token").matches("[a-f0-9]{64}"))throw new IOException("Invalid Google connection reply");m.put("token",claim.getString("token")).put("user",claim.getJSONObject("user")).put("enabled",false).put("error","");m.remove("pair");m.put("head",api(m,"meta",null));meta(c,vault,m);return false;}
  if(vault.exists("pending")){JSONObject waiting=vault.read("pending");if(waiting.optString("kind").equals("restore")){if(!finishRestore(c,vault,m))return false;}else if(waiting.has("uploaded")&&!m.optString("token").isEmpty()){m.put("enabled",true).put("boundId",waiting.getString("owner")).put("boundEmail",m.getJSONObject("user").getString("email"));}}
  if(m.optString("token").isEmpty()||!m.optBoolean("enabled"))return false;
  if(!m.optString("boundId").equals(m.getJSONObject("user").getString("id")))throw new IOException("This device belongs to another cloud account. Choose a cloud restore before syncing.");
  if(!finishPending(c,vault,m,resolution))return false;
  JSONObject base=vault.read("base");if(!base.optString("owner").equals(m.getJSONObject("user").getString("id")))throw new IOException("Choose a backup or restore to initialize this account safely.");
  JSONObject head=api(m,"meta",null);if(head.optLong("revision")==0){if(!m.optBoolean("needsInitialUpload"))throw new IOException("The cloud copy was removed. Reconnect before uploading again.");JSONObject before=SyncCore.snapshot(backup(c));validate(c,before);JSONObject ack=upload(m,before,0);m.put("needsInitialUpload",false);vault.write("pending",new JSONObject().put("owner",m.getJSONObject("user").getString("id")).put("before",before).put("uploaded",before).put("head",ack));return !finishPending(c,vault,m,"");}m.put("needsInitialUpload",false);JSONObject remote=readRemote(m,head.getLong("revision")),before=SyncCore.snapshot(backup(c));validate(c,remote);
  JSONObject oldConflict=vault.exists("conflict")?vault.read("conflict"):new JSONObject();if(!resolution.isEmpty()&&(oldConflict.optLong("revision")!=head.getLong("revision")||!oldConflict.has("local")||!SyncCore.same(oldConflict.getJSONObject("local"),before)))resolution="";
  SyncCore.Result merged=SyncCore.merge(base.getJSONObject("state"),before,remote,resolution);
  if(merged.conflicts.length()>0&&resolution.isEmpty()){vault.write("conflict",new JSONObject().put("phase","merge").put("base",base.getJSONObject("state")).put("local",before).put("remote",remote).put("revision",head.getLong("revision")).put("conflicts",merged.conflicts));m.put("head",head).put("error","");meta(c,vault,m);return false;}
  validate(c,merged.state);JSONObject ack=SyncCore.same(merged.state,remote)?head:upload(m,merged.state,head.getLong("revision"));vault.write("pending",new JSONObject().put("owner",m.getJSONObject("user").getString("id")).put("before",before).put("uploaded",merged.state).put("head",ack));return !finishPending(c,vault,m,"");
 }catch(Exception e){failure(c,vault,m,e);return !(e instanceof ApiError&&((ApiError)e).status==401);}}
 private static void confirm(MainActivity host,String title,String message,Runnable accepted){host.runOnUiThread(()->{if(host.isFinishing()||host.isDestroyed())return;new AlertDialog.Builder(host).setTitle(title).setMessage(message).setPositiveButton("Continue",(d,w)->execute(accepted)).setNegativeButton("Cancel",null).show();});}
 private static boolean finishRestore(Context c,CloudVault vault,JSONObject m)throws Exception{
  JSONObject intent=vault.read("pending");if(!intent.optString("kind").equals("restore"))return true;JSONObject marker;try(Store store=new Store(c)){marker=store.get("meta","cloud-restore-marker");}
  if(marker==null||!marker.optString("value").equals(intent.optString("id"))){vault.remove("pending");m.put("error","Restore was interrupted before records changed. Review the cloud copy and try again.");meta(c,vault,m);return false;}
  String owner=intent.getString("owner");if(!m.has("user")||!owner.equals(m.getJSONObject("user").optString("id")))throw new IOException("A restored workspace needs its original Google account");
  JSONObject baseline=intent.getJSONObject("baseline"),head=intent.getJSONObject("head");vault.write("base",new JSONObject().put("owner",owner).put("state",baseline));m.put("boundId",owner).put("boundEmail",m.getJSONObject("user").getString("email")).put("enabled",!m.optString("token").isEmpty()).put("head",head).put("needsInitialUpload",head.optLong("revision")==0).put("backupAt",head.optLong("updated")).put("lastSyncAt",head.optLong("revision")>0?System.currentTimeMillis():0).put("error","");
  c.getSharedPreferences("cloud-flags",Context.MODE_PRIVATE).edit().putBoolean("dirty",!SyncCore.same(SyncCore.snapshot(backup(c)),baseline)).apply();vault.remove("conflict");meta(c,vault,m);vault.remove("pending");return true;
 }
 private static void restore(Context c,CloudVault vault,JSONObject m,JSONObject target,JSONObject baseline,JSONObject head)throws Exception{
  validate(c,target);for(int attempt=0;attempt<3;attempt++){JSONObject current=backup(c);String marker=UUID.randomUUID().toString();vault.write("safety",new JSONObject().put("state",current).put("boundId",m.optString("boundId")).put("boundEmail",m.optString("boundEmail")));vault.write("pending",new JSONObject().put("kind","restore").put("id",marker).put("owner",m.getJSONObject("user").getString("id")).put("baseline",baseline).put("head",head));JSONObject composed=SyncCore.compose(current,target);CloudJobs.APPLYING.set(true);try(Store store=new Store(c)){try{store.restoreCloudWithMarker(current,composed,marker);}catch(java.util.ConcurrentModificationException e){vault.remove("pending");if(attempt==2)throw e;continue;}}finally{CloudJobs.APPLYING.remove();}finishRestore(c,vault,m);return;}
 }
 public static void action(MainActivity host,String action,long revision){execute(()->{CloudVault vault=new CloudVault(host);JSONObject m=new JSONObject();try{
  m=vault.read("meta");if(vault.exists("pending")&&vault.read("pending").optString("kind").equals("restore"))finishRestore(host,vault,m);final JSONObject account=m;
  if(action.equals("connect")){
   if(!m.optString("token").isEmpty()){host.tell("Google account is already connected");return;}String verifier=random(),challenge=android.util.Base64.encodeToString(MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(StandardCharsets.UTF_8)),android.util.Base64.URL_SAFE|android.util.Base64.NO_WRAP|android.util.Base64.NO_PADDING);JSONObject p=api(new JSONObject(),"pair.start",new JSONObject().put("challenge",challenge).put("device",Build.MANUFACTURER+" "+Build.MODEL));p.put("verifier",verifier);m.put("pair",p).put("error","");meta(host,vault,m);CloudJobs.schedule(host);openLogin(host,p);return;
  }
  if(action.equals("openLogin")){JSONObject p=m.optJSONObject("pair");if(p==null)throw new IOException("Start Google sign-in again");openLogin(host,p);return;}
  if(action.equals("sync")){run(host,"");return;}
  if(action.equals("disconnect")){confirm(host,"Use Local mode?","Sync will stop on this phone. Your local records and saved cloud copies will remain.",()->disconnect(host));return;}
  if(action.equals("local")||action.equals("remote")){confirm(host,"Resolve sync conflicts?","Use the "+(action.equals("local")?"phone":"cloud")+" version of the displayed conflicting fields? Other changes will still merge.",()->run(host,action));return;}
  if(m.optString("token").isEmpty())throw new IOException("Sign in with Google first");String email=m.getJSONObject("user").getString("email");JSONObject head=api(m,"meta",null);m.put("head",head);meta(host,vault,m);
  if(action.equals("delete")){confirm(host,"Delete Google cloud copies?","Delete all saved Paisa cloud copies for "+email+" and sign out synced devices? Local records will stay on each device.",()->{try{api(account,"delete",new JSONObject().put("revision",head.getLong("revision")));clearSession(host,vault,account);host.tell("Cloud copies deleted. Local records kept.");}catch(Exception e){failure(host,vault,account,e);}});return;}
  if(action.equals("resume")){JSONObject base=vault.read("base");if(!base.optString("owner").equals(m.getJSONObject("user").getString("id"))||!m.optString("boundId").equals(base.optString("owner")))throw new IOException("Restore or back up this account before enabling sync");confirm(host,"Resume Google sync?","Merge this phone's changes with the saved Paisa workspace for "+email+"? Conflicting edits will need review.",()->{try{account.put("enabled",true).put("error","");meta(host,vault,account);CloudJobs.schedule(host);run(host,"");}catch(Exception e){failure(host,vault,account,e);}});return;}
  if(action.equals("upload")||action.equals("replace")){
   if(!m.optString("boundId").isEmpty()&&!m.optString("boundId").equals(m.getJSONObject("user").getString("id")))throw new IOException("These local records belong to another Google account. Restore that account's cloud copy or start an empty workspace.");
   if(!action.equals("replace")&&head.optLong("revision")>0&&!empty(readRemote(m,head.getLong("revision"))))throw new IOException("This account already has a cloud copy. Restore it first; the current phone records will be kept in a safety copy.");
   int count=SyncCore.count(SyncCore.snapshot(backup(host)));confirm(host,action.equals("replace")?"Replace cloud with this phone?":"Back up this phone?",(action.equals("replace")?"Replace the current cloud workspace ("+head.optInt("entryCount")+" counted entries) with this phone. Up to five recent cloud versions remain available. ":"")+"Upload the current "+count+" counted entries, notes, accounts and budgets to Paisa cloud for "+email+"? Raw SMS are not uploaded.",()->{try{JSONObject liveHead=api(account,"meta",null);if(liveHead.optLong("revision")!=head.optLong("revision"))throw new IOException("Cloud data changed. Review it before backing up.");JSONObject before=SyncCore.snapshot(backup(host));validate(host,before);JSONObject ack=upload(account,before,head.optLong("revision"));account.put("enabled",true).put("boundId",account.getJSONObject("user").getString("id")).put("boundEmail",email);vault.write("base",new JSONObject().put("owner",account.getJSONObject("user").getString("id")).put("state",before));vault.write("pending",new JSONObject().put("owner",account.getJSONObject("user").getString("id")).put("before",before).put("uploaded",before).put("head",ack));meta(host,vault,account);finishPending(host,vault,account,"");CloudJobs.schedule(host);host.tell("Google backup confirmed. Sync is on.");}catch(Exception e){failure(host,vault,account,e);}});return;
  }
  if(action.equals("restore")||action.equals("new")){
   final long selected=revision>0?revision:head.optLong("revision");final JSONObject target;
   if(action.equals("new")){if(head.optLong("revision")>0)throw new IOException("Use the saved cloud copy for this account");target=SyncCore.snapshot(new JSONObject().put("entries",new JSONArray()).put("accounts",new JSONArray().put(new JSONObject().put("id","cash").put("name","Cash").put("type","cash").put("opening",0).put("openingAt",0)).put(new JSONObject().put("id","bank:default").put("name","Bank").put("type","bank").put("opening",0).put("openingAt",0))).put("bills",new JSONArray()).put("subscriptions",new JSONArray()).put("rules",new JSONArray()).put("settings",new JSONObject()));}
   else{if(selected<1)throw new IOException("No cloud copy is available");target=readRemote(m,selected);validate(host,target);}
   confirm(host,action.equals("new")?"Start an empty workspace?":"Restore cloud copy?","Use "+SyncCore.count(target)+" counted entries for "+email+" on this phone? Current records will be replaced after an encrypted on-device safety copy is saved.",()->{try{JSONObject latest=api(account,"meta",null);if(latest.optLong("revision")!=head.optLong("revision"))throw new IOException("Cloud data changed. Review the latest copy before restoring.");JSONObject baseline=latest.optLong("revision")>0?readRemote(account,latest.getLong("revision")):target;restore(host,vault,account,target,baseline,latest);CloudJobs.schedule(host);run(host,"");host.tell("Cloud copy restored. Previous phone records are kept in the safety copy.");}catch(Exception e){failure(host,vault,account,e);}});return;
  }
  throw new IOException("Unknown cloud action");
 }catch(Exception e){failure(host,vault,m,e);host.tell(e.getMessage());}});}
 private static void openLogin(MainActivity host,JSONObject pair)throws Exception{String link=ORIGIN+"/?pair="+Uri.encode(pair.getString("id"));confirm(host,"Connect Google account","In the browser, match connection code "+pair.getString("code")+". Approve only a request you started on this phone. No records are uploaded until you confirm a backup or restore in Paisa.",()->host.runOnUiThread(()->host.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(link)))));}
 private static void clearSession(Context c,CloudVault vault,JSONObject m)throws Exception{if(vault.exists("pending")&&vault.read("pending").optString("kind").equals("restore"))finishRestore(c,vault,m);m.remove("token");m.remove("pair");m.put("enabled",false).put("error","");vault.remove("conflict");vault.remove("pending");meta(c,vault,m);CloudJobs.cancel(c);try(Store store=new Store(c)){JSONObject cfg=store.settings().put("syncPreference","local");store.setSettings(cfg);}changed(c);}
 public static void disconnect(Context c){CloudVault vault=new CloudVault(c);try{JSONObject m=vault.read("meta"),old=new JSONObject(m.toString());clearSession(c,vault,m);if(old.has("pair")){JSONObject pair=old.getJSONObject("pair");try{api(new JSONObject(),"pair.cancel",new JSONObject().put("id",pair.getString("id")).put("verifier",pair.getString("verifier")));}catch(Exception ignored){}}if(!old.optString("token").isEmpty())try{api(old,"logout",new JSONObject());}catch(Exception ignored){} }catch(Exception ignored){}}
 public static void beforeManualRestore(Context c)throws Exception{
  EXECUTOR.submit(()->{try{CloudVault vault=new CloudVault(c);JSONObject m=vault.read("meta"),previous=new JSONObject(m.toString());clearSession(c,vault,m);m.remove("boundId");m.remove("boundEmail");vault.remove("base");meta(c,vault,m);if(!previous.optString("token").isEmpty())execute(()->{try{api(previous,"logout",new JSONObject());}catch(Exception ignored){}});}catch(Exception e){throw new IllegalStateException("Could not pause cloud sync safely",e);}}).get();
 }
 public static byte[] safety(Context c)throws Exception{JSONObject value=new CloudVault(c).read("safety");if(!value.has("state"))throw new IOException("No pre-sync safety copy is available");return value.getJSONObject("state").toString().getBytes(StandardCharsets.UTF_8);}
}
